/* Local homepage preview: retain product pixels and animate only the dark backdrop. */
(()=>{
 let cleanup=()=>{};
 window.setupHeroAurora=()=>{
  cleanup();
  const scene=document.querySelector('.hero-art');
  if(!scene)return;
  const img=scene.querySelector('img'),canvas=scene.querySelector('canvas'),ctx=canvas.getContext('2d');
  const W=1200,H=467,mask=document.createElement('canvas');
  canvas.width=mask.width=W;canvas.height=mask.height=H;
  const maskSource=new Image();maskSource.src='data:image/jpeg;base64,';
  const m=mask.getContext('2d'),motion=matchMedia('(prefers-reduced-motion: reduce)');
  let frame=0,disposed=false,ready=false,visible=true,time=0,last=0;
  function draw(){
   ctx.clearRect(0,0,W,H);ctx.globalCompositeOperation='screen';
   const colors=['72,208,213','102,129,228','201,134,204'];
   for(let j=0;j<3;j++)for(let layer=0;layer<3;layer++){
    ctx.beginPath();
    for(let x=-30;x<W+30;x+=5){const p=x/W,y=H*(.10+Math.sin(p*5.4+time*.24+j*.95)*.10+Math.sin(p*10.8-time*.16+j)*.027)+j*23;if(x===-30)ctx.moveTo(x,y);else ctx.lineTo(x,y+layer*3);}
    ctx.strokeStyle=`rgba(${colors[j]},${[.10,.19,.40][layer]})`;ctx.lineWidth=[55,19,2.4][layer];ctx.shadowColor=`rgba(${colors[j]},.65)`;ctx.shadowBlur=[30,21,11][layer];ctx.stroke();
   }
   ctx.shadowBlur=0;
   for(let i=0;i<18;i++){const x=(i*149.7+Math.sin(time*.14+i)*19)%W,y=H*(.03+((i*47)%250)/800)+Math.sin(time*.3+i)*7;ctx.beginPath();ctx.arc(x,y,1.2,0,Math.PI*2);ctx.fillStyle=`rgba(210,222,246,${.12+.12*(1+Math.sin(time*.6+i))/2})`;ctx.fill();}
   ctx.globalCompositeOperation='destination-in';ctx.drawImage(mask,0,0);ctx.globalCompositeOperation='source-over';
  }
  function tick(now){frame=0;if(disposed||!ready||!visible||document.hidden||motion.matches)return;time+=last?Math.min((now-last)/1000,.05):0;last=now;draw();frame=requestAnimationFrame(tick);}
  function resume(){cancelAnimationFrame(frame);frame=0;last=0;if(ready){draw();if(visible&&!document.hidden&&!motion.matches)frame=requestAnimationFrame(tick);}}
  function init(){
   if(disposed)return;
   if(!maskSource.complete||!maskSource.naturalWidth){maskSource.addEventListener('load',init,{once:true});return;}
   try{
    m.drawImage(maskSource,0,maskSource.naturalHeight*.308,maskSource.naturalWidth,maskSource.naturalHeight*.692,0,0,W,H);
    const pixels=m.getImageData(0,0,W,H);
    for(let i=0;i<pixels.data.length;i+=4){const brightness=Math.max(pixels.data[i],pixels.data[i+1],pixels.data[i+2]),y=Math.floor(i/4/W)/H;pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=255;pixels.data[i+3]=Math.round(Math.max(0,Math.min(1,(45-brightness)/30))*Math.max(0,Math.min(1,(.52-y)*8))*255);}
    m.putImageData(pixels,0,0);ready=true;resume();
   }catch(error){/* File previews may restrict canvas reads; the product image remains usable. */canvas.hidden=true;}
  }
  const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;resume();});observer.observe(scene);
  img.addEventListener('load',init,{once:true});if(img.complete&&img.naturalWidth)init();
  document.addEventListener('visibilitychange',resume);motion.addEventListener('change',resume);
  cleanup=()=>{disposed=true;cancelAnimationFrame(frame);observer.disconnect();img.removeEventListener('load',init);document.removeEventListener('visibilitychange',resume);motion.removeEventListener('change',resume);};
 };
})();
